import{_ as t,o as a,c as o,a0 as n}from"./chunks/framework.BTg7EidG.js";const i="/athanor-docs/screens/settings.png",p=JSON.parse('{"title":"Settings & Unlocks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md"}'),r={name:"guide/settings.md"};function s(h,e,l,d,u,g){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="settings-unlocks" tabindex="-1">Settings &amp; Unlocks <a class="header-anchor" href="#settings-unlocks" aria-label="Permalink to &quot;Settings &amp; Unlocks&quot;">​</a></h1><h2 id="the-menu" tabindex="-1">The menu <a class="header-anchor" href="#the-menu" aria-label="Permalink to &quot;The menu&quot;">​</a></h2><p><img src="'+i+'" alt="The settings menu"></p><p><strong>Settings</strong> on the main menu opens the sound and play options before a campaign starts. Once you are playing, the same menu lives behind the <strong>gear</strong> button on the world map&#39;s top bar — with saving and leaving added to it. On a phone the system back button opens it too.</p><h3 id="sound" tabindex="-1">Sound <a class="header-anchor" href="#sound" aria-label="Permalink to &quot;Sound&quot;">​</a></h3><ul><li><strong>Music on / off</strong> — the toggle silences the score without forgetting what was playing; turn it back on and the track picks up again.</li><li><strong>Volume</strong> — applies immediately to whatever is playing.</li></ul><p>Browsers refuse to play sound until you have touched the page, so the music starts on your first tap or click. If a browser tab is silent, check the ♪ button — a mute you set in an earlier session is remembered.</p><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><p><strong>Fullscreen</strong> appears in the browser version only, and hands the whole screen to the game. Press <kbd>Esc</kbd> to come back out. The phone app is already edge to edge and has no such setting.</p><h3 id="tutorial" tabindex="-1">Tutorial <a class="header-anchor" href="#tutorial" aria-label="Permalink to &quot;Tutorial&quot;">​</a></h3><p><strong>Guided turn</strong> switches the walkthrough on or off, and <strong>Reset tutorial</strong> offers the whole tour again from the beginning — the opening sequence and every one-off hint.</p><h3 id="guide" tabindex="-1">Guide <a class="header-anchor" href="#guide" aria-label="Permalink to &quot;Guide&quot;">​</a></h3><p><strong>Player guide ↗</strong> opens this manual in a browser.</p><h3 id="battle" tabindex="-1">Battle <a class="header-anchor" href="#battle" aria-label="Permalink to &quot;Battle&quot;">​</a></h3><p><strong>Auto-resolve</strong> decides whether the encounter dialog offers to settle a fight with the dice. Switch it off and every battle is fought on the tactical field — the shortcut simply stops being offered.</p><h3 id="campaign" tabindex="-1">Campaign <a class="header-anchor" href="#campaign" aria-label="Permalink to &quot;Campaign&quot;">​</a></h3><p>Only while a campaign is running: <strong>Save</strong>, <strong>Save &amp; quit</strong>, and <strong>Quit without saving</strong>. The day&#39;s autosave stands either way — see <a href="/athanor-docs/guide/saving.html">Saving Your Campaign</a>.</p><h2 id="what-you-unlock" tabindex="-1">What you unlock <a class="header-anchor" href="#what-you-unlock" aria-label="Permalink to &quot;What you unlock&quot;">​</a></h2><p>Your first campaign is offered plainly: no difficulty to weigh before you know what any of it means, and no seat at the heart of the chamber to take. Finishing the Great Work opens the rest, and what you have earned is kept on your device across campaigns.</p><table tabindex="0"><thead><tr><th>Do this</th><th>And this opens</th></tr></thead><tbody><tr><td>Win a campaign, at any difficulty</td><td>The <strong>difficulty</strong> choice appears on the guild confirmation screen</td></tr><tr><td>Win a campaign on <strong>Hard</strong></td><td>The <strong>seat at the heart</strong> opens: Entropy becomes playable</td></tr></tbody></table><h3 id="difficulty" tabindex="-1">Difficulty <a class="header-anchor" href="#difficulty" aria-label="Permalink to &quot;Difficulty&quot;">​</a></h3><p>Until you have won once, every campaign runs at the gentlest setting: your opening treasury is doubled. After that first victory you may pick for yourself:</p><ul><li><strong>Easy</strong> — doubles your opening treasury.</li><li><strong>Medium</strong> — everyone starts even.</li><li><strong>Hard</strong> — every rival guild&#39;s opening treasury is half again as large as it should be.</li></ul><h3 id="playing-entropy" tabindex="-1">Playing Entropy <a class="header-anchor" href="#playing-entropy" aria-label="Permalink to &quot;Playing Entropy&quot;">​</a></h3><p>Until then, Entropy simply stands at the middle of the chamber floor — present, the way it is present at the middle of the world, but not on offer. Win on Hard and that presence becomes a seat you can take. It is a different game from the other side: you begin at the world&#39;s blighted heart holding the Grand Athanor everyone else is coming to take, your swallowed garrisons draw no wages, and there is no temple to storm for victory. You win by ending every other guild — and you lose the moment your own Lord falls, exactly like anyone else.</p>',25)])])}const y=t(r,[["render",s]]);export{p as __pageData,y as default};
